package adapters

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

const codexMetadataLineLimit = 8 * 1024 * 1024

type CodexScanner struct {
	Home string
}

func (s CodexScanner) Name() string {
	return "codex"
}

func (s CodexScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	var messages []string
	sessionsRoot := filepath.Join(s.Home, "sessions")
	if !core.ExistingDir(sessionsRoot) {
		result.Skipped = true
		result.Message = "Codex sessions directory not found"
		return result
	}
	names, err := readCodexSessionNames(filepath.Join(s.Home, "session_index.jsonl"))
	if err != nil {
		names = make(map[string]string)
		messages = append(messages, fmt.Sprintf("Codex session name index unavailable: %v", err))
	}

	candidates := make(map[string]codexCandidate)
	unreadableRollouts := 0
	var firstUnreadable error
	recordUnreadable := func(err error) {
		unreadableRollouts++
		if firstUnreadable == nil {
			firstUnreadable = err
		}
	}
	err = filepath.WalkDir(sessionsRoot, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if entry.IsDir() ||
			!strings.HasPrefix(entry.Name(), "rollout-") ||
			filepath.Ext(entry.Name()) != ".jsonl" {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			recordUnreadable(fmt.Errorf("%s: reading file metadata: %w", path, err))
			return nil
		}
		if !info.Mode().IsRegular() {
			return nil
		}
		metadata, err := readCodexRolloutMetadata(path)
		if err != nil {
			recordUnreadable(err)
			return nil
		}
		if !metadata.resumable() {
			return nil
		}
		candidate := codexCandidate{metadata: metadata, path: path, updatedAt: info.ModTime().UTC()}
		existing, found := candidates[metadata.ID]
		if !found ||
			candidate.updatedAt.After(existing.updatedAt) ||
			(candidate.updatedAt.Equal(existing.updatedAt) && candidate.path > existing.path) {
			candidates[metadata.ID] = candidate
		}
		return nil
	})
	if err != nil {
		result.Err = fmt.Errorf("scanning Codex sessions: %w", err)
		return result
	}

	result.Sessions = make([]core.Session, 0, len(candidates))
	for _, candidate := range candidates {
		metadata := candidate.metadata
		title := strings.TrimSpace(names[metadata.ID])
		if title == "" {
			title = "Codex: " + core.ProjectName(metadata.CWD)
		}
		session := core.NewSession("codex", metadata.ID)
		session.ProjectPath = metadata.CWD
		session.Agent = "codex"
		session.Title = core.Truncate(title, 120)
		session.Status = core.StatusUnknown
		session.CreatedAt = metadata.CreatedAt
		session.LastActivityAt = candidate.updatedAt
		resume := commandWithEnv("CODEX_HOME", s.Home, "codex resume "+core.ShellQuote(metadata.ID))
		session.ResumeCommand = resumeInDirectory(metadata.CWD, resume)
		session.RawPath = candidate.path
		result.Sessions = append(result.Sessions, session)
	}
	sort.Slice(result.Sessions, func(i, j int) bool {
		if result.Sessions[i].LastActivityAt.Equal(result.Sessions[j].LastActivityAt) {
			return result.Sessions[i].NativeID < result.Sessions[j].NativeID
		}
		return result.Sessions[i].LastActivityAt.After(result.Sessions[j].LastActivityAt)
	})
	if unreadableRollouts > 0 {
		messages = append(messages, fmt.Sprintf(
			"Codex scan incomplete: skipped %d unreadable rollout(s); first error: %v",
			unreadableRollouts,
			firstUnreadable,
		))
	}
	result.Message = strings.Join(messages, "; ")
	result.SessionSnapshotComplete = unreadableRollouts == 0
	return result
}

type codexCandidate struct {
	metadata  codexMetadata
	path      string
	updatedAt time.Time
}

type codexRolloutLine struct {
	Timestamp string          `json:"timestamp"`
	Type      string          `json:"type"`
	Payload   json.RawMessage `json:"payload"`
}

type codexMetadata struct {
	ID           string          `json:"id"`
	ParentThread *string         `json:"parent_thread_id"`
	Timestamp    string          `json:"timestamp"`
	CWD          string          `json:"cwd"`
	Source       json.RawMessage `json:"source"`
	HistoryMode  string          `json:"history_mode"`
	CreatedAt    time.Time       `json:"-"`
}

func (metadata codexMetadata) resumable() bool {
	if metadata.ID == "" || metadata.CWD == "" || !filepath.IsAbs(metadata.CWD) || metadata.CreatedAt.IsZero() {
		return false
	}
	if metadata.ParentThread != nil && strings.TrimSpace(*metadata.ParentThread) != "" {
		return false
	}
	if metadata.HistoryMode != "" &&
		metadata.HistoryMode != "legacy" &&
		metadata.HistoryMode != "paginated" {
		return false
	}
	return codexInteractiveSource(metadata.Source)
}

func readCodexRolloutMetadata(path string) (codexMetadata, error) {
	file, err := os.Open(path)
	if err != nil {
		return codexMetadata{}, err
	}
	defer file.Close() //nolint:errcheck
	reader := bufio.NewReaderSize(file, 64*1024)
	line, err := readBoundedLine(reader, codexMetadataLineLimit)
	if err != nil {
		return codexMetadata{}, fmt.Errorf("%s: reading first rollout line: %w", path, err)
	}
	if len(line) == 0 {
		return codexMetadata{}, fmt.Errorf("%s: empty or oversized first rollout line", path)
	}
	var envelope codexRolloutLine
	if err := json.Unmarshal(line, &envelope); err != nil {
		return codexMetadata{}, fmt.Errorf("%s: invalid first rollout line: %w", path, err)
	}
	if envelope.Type != "session_meta" {
		return codexMetadata{}, fmt.Errorf("%s: first rollout item is %q, want session_meta", path, envelope.Type)
	}
	var metadata codexMetadata
	if err := json.Unmarshal(envelope.Payload, &metadata); err != nil {
		return codexMetadata{}, fmt.Errorf("%s: invalid session metadata: %w", path, err)
	}
	metadata.ID = strings.TrimSpace(metadata.ID)
	metadata.CWD = filepath.Clean(strings.TrimSpace(metadata.CWD))
	metadata.HistoryMode = strings.ToLower(strings.TrimSpace(metadata.HistoryMode))
	metadata.CreatedAt = parseTimeString(firstNonEmpty(metadata.Timestamp, envelope.Timestamp))
	if metadata.ID == "" {
		return codexMetadata{}, fmt.Errorf("%s: session metadata has empty thread id", path)
	}
	if metadata.CWD == "." || metadata.CWD == "" || !filepath.IsAbs(metadata.CWD) {
		return codexMetadata{}, fmt.Errorf("%s: session metadata has invalid cwd %q", path, metadata.CWD)
	}
	if metadata.CreatedAt.IsZero() {
		return codexMetadata{}, fmt.Errorf("%s: session metadata has invalid timestamp", path)
	}
	return metadata, nil
}

func codexInteractiveSource(raw json.RawMessage) bool {
	if len(raw) == 0 {
		return true // SessionSource defaults to VSCode.
	}
	if string(raw) == "null" {
		return false
	}
	var source string
	if err := json.Unmarshal(raw, &source); err == nil {
		source = strings.ToLower(strings.TrimSpace(source))
		return source == "cli" || source == "vscode"
	}
	var custom map[string]string
	if err := json.Unmarshal(raw, &custom); err != nil {
		return false
	}
	value := strings.ToLower(strings.TrimSpace(custom["custom"]))
	return value == "atlas" || value == "chatgpt"
}

type codexSessionIndexEntry struct {
	ID         string `json:"id"`
	ThreadName string `json:"thread_name"`
	UpdatedAt  string `json:"updated_at"`
}

func readCodexSessionNames(path string) (map[string]string, error) {
	names := make(map[string]string)
	file, err := os.Open(path)
	if os.IsNotExist(err) {
		return names, nil
	}
	if err != nil {
		return nil, fmt.Errorf("opening %s: %w", path, err)
	}
	defer file.Close() //nolint:errcheck
	reader := bufio.NewReaderSize(file, 64*1024)
	for {
		line, err := readBoundedLine(reader, 1024*1024)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", path, err)
		}
		if len(line) == 0 {
			continue
		}
		var entry codexSessionIndexEntry
		if json.Unmarshal(line, &entry) != nil {
			continue
		}
		entry.ID = strings.TrimSpace(entry.ID)
		entry.ThreadName = strings.TrimSpace(entry.ThreadName)
		if entry.ID != "" {
			names[entry.ID] = entry.ThreadName
		}
	}
	return names, nil
}

package adapters

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

func TestCodexScannerEnumeratesResumableInteractiveThreads(t *testing.T) {
	home := t.TempDir()
	sessions := filepath.Join(home, "sessions")
	old := time.Unix(100, 0)
	newer := time.Unix(200, 0)

	writeCodexRollout(t, sessions, "rollout-legacy-thread-flat.jsonl", codexPayload(
		"thread-flat", "/repo/flat", "cli", nil, "legacy", "2026-01-01T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/02/rollout-old-thread-cli.jsonl", codexPayload(
		"thread-cli", "/repo/old", "cli", nil, "legacy", "2026-01-02T00:00:00Z",
	), old)
	newestPath := writeCodexRollout(t, sessions, "2026/01/03/rollout-new-thread-cli_rollout.jsonl", codexPayload(
		"thread-cli", "/repo/new", "cli", nil, "paginated", "2026-01-03T00:00:00Z",
	), newer)
	writeCodexRollout(t, sessions, "2026/01/04/rollout-vscode.jsonl", codexPayload(
		"thread-vscode", "/repo/vscode", nil, nil, "", "2026-01-04T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/05/rollout-atlas.jsonl", codexPayload(
		"thread-atlas", "/repo/atlas", map[string]string{"custom": "atlas"}, nil, "legacy", "2026-01-05T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/06/rollout-chatgpt.jsonl", codexPayload(
		"thread-chatgpt", "/repo/chatgpt", map[string]string{"custom": "chatgpt"}, nil, "legacy", "2026-01-06T00:00:00Z",
	), old)
	fork := codexPayload(
		"thread-fork", "/repo/fork", "cli", nil, "legacy", "2026-01-06T12:00:00Z",
	)
	fork["forked_from_id"] = "thread-cli"
	writeCodexRollout(t, sessions, "2026/01/06/rollout-fork.jsonl", fork, old)

	parent := "thread-cli"
	writeCodexRollout(t, sessions, "2026/01/07/rollout-subagent.jsonl", codexPayload(
		"thread-subagent", "/repo/subagent", "cli", &parent, "legacy", "2026-01-07T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/08/rollout-exec.jsonl", codexPayload(
		"thread-exec", "/repo/exec", "exec", nil, "legacy", "2026-01-08T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/09/rollout-custom.jsonl", codexPayload(
		"thread-custom", "/repo/custom", map[string]string{"custom": "other"}, nil, "legacy", "2026-01-09T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/10/rollout-future.jsonl", codexPayload(
		"thread-future", "/repo/future", "cli", nil, "future", "2026-01-10T00:00:00Z",
	), old)
	nullSource := codexPayload(
		"thread-null", "/repo/null", nil, nil, "legacy", "2026-01-11T00:00:00Z",
	)
	nullSource["source"] = nil
	writeCodexRollout(t, sessions, "2026/01/11/rollout-null-source.jsonl", nullSource, old)
	writeCodexRollout(t, sessions, "2026/01/12/rollout-internal.jsonl", codexPayload(
		"thread-internal", "/repo/internal", map[string]any{"internal": "compact"}, nil, "legacy", "2026-01-12T00:00:00Z",
	), old)
	writeCodexRollout(t, sessions, "2026/01/13/rollout-source-subagent.jsonl", codexPayload(
		"thread-source-subagent", "/repo/subagent", map[string]any{"subagent": "review"}, nil, "legacy", "2026-01-13T00:00:00Z",
	), old)
	if err := os.WriteFile(filepath.Join(sessions, "unrelated.jsonl"), []byte("{\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(sessions, "rollout-compressed.jsonl.zst"), []byte("{\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	linkTarget := filepath.Join(home, "private-rollout.jsonl")
	if err := os.WriteFile(linkTarget, []byte("{\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(linkTarget, filepath.Join(sessions, "rollout-linked.jsonl")); err != nil {
		t.Logf("symlink fixture unavailable: %v", err)
	}
	archived := filepath.Join(home, "archived_sessions", "rollout-archived.jsonl")
	if err := os.MkdirAll(filepath.Dir(archived), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(archived, []byte("{\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	index := strings.Join([]string{
		`{"id":"thread-cli","thread_name":"old name","updated_at":"2026-01-02T00:00:00Z"}`,
		`not-json`,
		`{"id":"thread-cli","thread_name":"renamed thread","updated_at":"2026-01-03T00:00:00Z"}`,
		`{"id":"thread-flat","thread_name":"flat thread","updated_at":"2026-01-01T00:00:00Z"}`,
	}, "\n") + "\n"
	if err := os.WriteFile(filepath.Join(home, "session_index.jsonl"), []byte(index), 0o644); err != nil {
		t.Fatal(err)
	}

	result := (CodexScanner{Home: home}).Scan(context.Background())
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	if !result.SessionSnapshotComplete {
		t.Fatal("successful Codex scan must be authoritative")
	}
	if len(result.Sessions) != 6 {
		t.Fatalf("sessions = %d, want 6: %+v", len(result.Sessions), result.Sessions)
	}

	thread := findNativeSession(t, result.Sessions, "thread-cli")
	if thread.ProjectPath != "/repo/new" || thread.Title != "renamed thread" || thread.RawPath != newestPath {
		t.Fatalf("unexpected deduplicated thread: %+v", thread)
	}
	if thread.CreatedAt != time.Date(2026, 1, 3, 0, 0, 0, 0, time.UTC) ||
		!thread.LastActivityAt.Equal(newer.UTC()) {
		t.Fatalf("unexpected timestamps: %+v", thread)
	}
	wantResume := "cd '/repo/new' && CODEX_HOME=" +
		core.ShellQuote(home) + " codex resume 'thread-cli'"
	if thread.ResumeCommand != wantResume {
		t.Fatalf("resume = %q, want %q", thread.ResumeCommand, wantResume)
	}
	if findNativeSession(t, result.Sessions, "thread-flat").Title != "flat thread" {
		t.Fatal("flat layout or session name not indexed")
	}
	findNativeSession(t, result.Sessions, "thread-fork")
	if strings.Contains(fmt.Sprint(result.Sessions), "private-value-not-read") {
		t.Fatal("ignored Codex repository URL leaked into normalized sessions")
	}
}

func TestCodexScannerSkipsMissingStore(t *testing.T) {
	result := (CodexScanner{Home: t.TempDir()}).Scan(context.Background())
	if !result.Skipped || result.Err != nil {
		t.Fatalf("missing store result: %+v", result)
	}
}

func TestCodexScannerTreatsNameIndexAsOptionalEnrichment(t *testing.T) {
	home := t.TempDir()
	writeCodexRollout(t, filepath.Join(home, "sessions"), "rollout-thread.jsonl", codexPayload(
		"thread", "/repo/project", "cli", nil, "legacy", "2026-01-01T00:00:00Z",
	), time.Unix(100, 0))
	if err := os.Mkdir(filepath.Join(home, "session_index.jsonl"), 0o755); err != nil {
		t.Fatal(err)
	}

	result := (CodexScanner{Home: home}).Scan(context.Background())
	if result.Err != nil || !result.SessionSnapshotComplete || len(result.Sessions) != 1 {
		t.Fatalf("optional index blocked scan: %+v", result)
	}
	if result.Message == "" || result.Sessions[0].Title != "Codex: project" {
		t.Fatalf("index warning or fallback title missing: %+v", result)
	}
}

func TestCodexScannerRejectsMalformedAuthoritativeMetadata(t *testing.T) {
	tests := []struct {
		name string
		line string
	}{
		{name: "invalid json", line: "{"},
		{name: "wrong item", line: `{"timestamp":"2026-01-01T00:00:00Z","type":"response_item","payload":{}}`},
		{name: "missing id", line: `{"timestamp":"2026-01-01T00:00:00Z","type":"session_meta","payload":{"cwd":"/repo","timestamp":"2026-01-01T00:00:00Z","source":"cli"}}`},
		{name: "relative cwd", line: `{"timestamp":"2026-01-01T00:00:00Z","type":"session_meta","payload":{"id":"id","cwd":"repo","timestamp":"2026-01-01T00:00:00Z","source":"cli"}}`},
		{name: "invalid timestamp", line: `{"timestamp":"invalid","type":"session_meta","payload":{"id":"id","cwd":"/repo","timestamp":"invalid","source":"cli"}}`},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			home := t.TempDir()
			path := filepath.Join(home, "sessions", "rollout-test.jsonl")
			if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, []byte(test.line+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			result := (CodexScanner{Home: home}).Scan(context.Background())
			if result.Err != nil || result.SessionSnapshotComplete || result.Message == "" {
				t.Fatalf("malformed rollout did not produce an incomplete warning: %+v", result)
			}
		})
	}
}

func TestCodexRolloutUsesOuterTimestampFallback(t *testing.T) {
	home := t.TempDir()
	path := filepath.Join(home, "sessions", "rollout-fallback.jsonl")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	line := `{"timestamp":"2026-01-01T00:00:00Z","type":"session_meta","payload":{"id":"id","cwd":"/repo","source":"cli"}}`
	if err := os.WriteFile(path, []byte(line+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	result := (CodexScanner{Home: home}).Scan(context.Background())
	if result.Err != nil || len(result.Sessions) != 1 {
		t.Fatalf("outer timestamp fallback failed: %+v", result)
	}
	if got := result.Sessions[0].CreatedAt; got != time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC) {
		t.Fatalf("created at = %s", got)
	}
}

func TestCodexScannerRejectsOversizedMetadataLine(t *testing.T) {
	home := t.TempDir()
	path := filepath.Join(home, "sessions", "rollout-test.jsonl")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	line := `{"timestamp":"2026-01-01T00:00:00Z","type":"session_meta","payload":{"id":"id","cwd":"/repo","timestamp":"2026-01-01T00:00:00Z","source":"cli","base_instructions":"` +
		strings.Repeat("x", codexMetadataLineLimit+1) + `"}}`
	if err := os.WriteFile(path, []byte(line+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	result := (CodexScanner{Home: home}).Scan(context.Background())
	if result.Err != nil || result.SessionSnapshotComplete || result.Message == "" {
		t.Fatalf("oversized metadata did not produce an incomplete warning: %+v", result)
	}
}

func codexPayload(id, cwd string, source any, parent *string, historyMode, timestamp string) map[string]any {
	payload := map[string]any{
		"session_id":       "session-" + id,
		"id":               id,
		"parent_thread_id": parent,
		"timestamp":        timestamp,
		"cwd":              cwd,
		"originator":       "codex-cli",
		"cli_version":      "1.0.0",
		"history_mode":     historyMode,
		"git": map[string]any{
			"branch":         "main",
			"commit_hash":    "abc123",
			"repository_url": "private-value-not-read",
		},
	}
	if source != nil {
		payload["source"] = source
	}
	return payload
}

func writeCodexRollout(t *testing.T, sessionsRoot, relative string, payload map[string]any, modified time.Time) string {
	t.Helper()
	path := filepath.Join(sessionsRoot, filepath.FromSlash(relative))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	line, err := json.Marshal(map[string]any{
		"timestamp": payload["timestamp"],
		"ordinal":   0,
		"type":      "session_meta",
		"payload":   payload,
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, append(line, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Chtimes(path, modified, modified); err != nil {
		t.Fatal(err)
	}
	return path
}

package adapters

import (
	"context"

	"github.com/jdbencardinop/tesserasessions/internal/config"
	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type Scanner interface {
	Name() string
	Scan(context.Context) core.ScanResult
}

func DefaultScanners(cfg config.Config) []Scanner {
	scanners := []Scanner{
		ClaudeScanner{Root: cfg.Sources.ClaudeProjects},
		CopilotScanner{Root: cfg.Sources.CopilotSessionState},
		HermesHistoryScanner{Database: cfg.Sources.HermesDatabase},
		OpenCodeScanner{Database: cfg.Sources.OpenCodeDatabase},
		CodexScanner{Home: cfg.Sources.CodexHome},
	}
	return append(scanners, LiveScanners()...)
}

func LiveScanners() []Scanner {
	return []Scanner{
		HerdrScanner{},
		TmuxScanner{},
	}
}

func resumeInDirectory(directory, command string) string {
	if directory == "" {
		return command
	}
	return "cd " + core.ShellQuote(directory) + " && " + command
}

func commandWithEnv(name, value, command string) string {
	if value == "" {
		return command
	}
	return name + "=" + core.ShellQuote(value) + " " + command
}

package cli

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/adapters"
	"github.com/jdbencardinop/tesserasessions/internal/buildinfo"
	"github.com/jdbencardinop/tesserasessions/internal/config"
	"github.com/jdbencardinop/tesserasessions/internal/core"
	"github.com/jdbencardinop/tesserasessions/internal/store"
	"github.com/jdbencardinop/tesserasessions/internal/summarize"
