)

type appContext struct {
	configPath string
	dbPath     string
}

func mergeSessions(primary, secondary []core.Session) []core.Session {
	seen := make(map[string]bool)
	var out []core.Session
	for _, sess := range primary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	for _, sess := range secondary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	return out
}

